[CmdletBinding(SupportsShouldProcess)]
param([Parameter(Mandatory)][string]$PackageRoot,[Parameter(Mandatory)][string]$TargetRoot,[switch]$ForceRepair)
$ErrorActionPreference='Stop';$mPath=Join-Path $PackageRoot 'ES/Automation/ABCD/es-abcd-generic-package.manifest.json';if(-not(Test-Path -LiteralPath $mPath -PathType Leaf)){throw 'ABCD_GENERIC_MANIFEST_MISSING'};$m=Get-Content $mPath -Raw -Encoding UTF8|ConvertFrom-Json;$missingDirs=[Collections.Generic.List[string]]::new();$missingFiles=[Collections.Generic.List[string]]::new();$mismatch=[Collections.Generic.List[string]]::new();$repaired=[Collections.Generic.List[string]]::new();$sourceCount=0
foreach($d in @($m.requiredDirectories)){$sd=Join-Path $PackageRoot $d;if(-not(Test-Path -LiteralPath $sd -PathType Container)){[void]$missingDirs.Add($d);continue};$td=Join-Path $TargetRoot $d;if(-not(Test-Path -LiteralPath $td -PathType Container)){New-Item -ItemType Directory -Force -Path $td|Out-Null};foreach($f in @(Get-ChildItem $sd -Recurse -File)){$sourceCount++;$rel=$f.FullName.Substring($PackageRoot.Length+1).Replace('\','/');$dst=Join-Path $TargetRoot $rel;if(-not(Test-Path -LiteralPath $dst -PathType Leaf)){if($PSCmdlet.ShouldProcess($dst,'restore missing generic ABCD file')){New-Item -ItemType Directory -Force -Path (Split-Path $dst)|Out-Null;Copy-Item $f.FullName $dst -Force;[void]$repaired.Add($rel)}else{[void]$missingFiles.Add($rel)}}elseif((Get-FileHash $f.FullName -Algorithm SHA256).Hash -ne (Get-FileHash $dst -Algorithm SHA256).Hash){[void]$mismatch.Add($rel);if($ForceRepair -and $PSCmdlet.ShouldProcess($dst,'replace mismatched generic ABCD file')){Copy-Item $f.FullName $dst -Force;[void]$repaired.Add($rel)}}}}
$status=if($missingDirs.Count -or $missingFiles.Count){'package-invalid'}elseif($mismatch.Count -and -not $ForceRepair){'review-required'}else{'restored-or-present'};[ordered]@{schemaVersion=1;packageId=$m.packageId;status=$status;businessFree=$m.businessFree;sourceFileCount=$sourceCount;missingDirectories=@($missingDirs);missingFiles=@($missingFiles|Select-Object -Unique);hashMismatches=@($mismatch|Select-Object -Unique);repaired=@($repaired|Select-Object -Unique);coreCapabilityGapForbidden=$true;runtimeStatus='not-run';claimsNotProven=@('Unity','PlayMode','Profiler','Release');authority='ABCD-final-decision'}|ConvertTo-Json -Depth 10
